            {
                tree[node] = arr[l];
                return;
            }
            int mid = (l + r) >> 1;
            RunInt32(arr, tree, node * 2, l, mid);
            RunInt32(arr, tree, node * 2 + 1, mid + 1, r);
            tree[node] = tree[node * 2] + tree[node * 2 + 1];
        }

